import { Column, CreateDateColumn, Entity, PrimaryColumn, Unique, UpdateDateColumn } from 'typeorm';
import type { Permission } from '../../modules/permissions/permission.js';
import type { Role } from '../../modules/roles/role.js';

export const ROLES_NAME_UNIQUE = 'roles_name_unique';

@Entity({ name: 'roles' })
@Unique(ROLES_NAME_UNIQUE, ['name'])
export class RoleEntity implements Role {
  /** A UUIDv7 generated by the repository, so ids sort by creation time. */
  @PrimaryColumn({ type: 'uuid', primaryKeyConstraintName: 'roles_pkey' })
  id!: string;

  @Column({ type: 'text' })
  name!: string;

  @Column({ type: 'text' })
  description!: string;

  @Column({ type: 'text', array: true })
  permissions!: Permission[];

  @Column({ name: 'is_system', type: 'boolean', default: false })
  isSystem!: boolean;

  @CreateDateColumn({ name: 'created_at', type: 'timestamptz' })
  createdAt!: Date;

  /** Set to the current time by every update. */
  @UpdateDateColumn({ name: 'updated_at', type: 'timestamptz' })
  updatedAt!: Date;
}
